globalThis.NSI_TEMPLATE = {"base64": "", "purposes": ["{{purpose_0}}初次认证第一阶段：根据认证申请，通过审核收集与受审核方管理体系的认证范围、产品/服务、过程、场所等有关的信息以实现以下目的：", "1、审核客户的文件化的管理体系信息； ", "2、评价客户现场的具体情况，并与客户的人员进行讨论，以确定第二阶段的准备情况； ", "3、审查客户理解和实施标准要求的情况，特别是对管理体系的关键绩效或重要的因素、过程、目标和运作的识别情况； ", "4、收集关于客户的管理体系范围的必要信息，包括：客户的场所、使用的过程和设备、所建立的控制的水平（特别是客户为多场所时）、适用的法律法规要求； ", "5、审查第二阶段所需资源的配置情况，并与客户商定第二阶段的细节； ", "6、结合管理体系标准或其他规范性文件充分了解客户的管理体系和现场运作，以便为策划第二阶段提供关注点； ", "7、评价客户是否策划和实施了内部审核与管理评审，以及管理体系的实施程度能否证明客户已为第二阶段做好准备。", "{{purpose_1}}初次认证第二阶段：通过对受审核方管理体系的符合性和有效性，以及与认证范围的相关性和适宜性评价，确认能否推荐初次认证注册。", "{{purpose_2}}监督审核：通过对受审核方管理体系持续运作有效性的评价，确认能否推荐保持认证。", "{{purpose_3}}再认证：通过对受审核方管理体系整体的持续符合性和有效性，以及与认证范围的持续相关性和适宜性评价，确认能否推荐再认证注册。", "{{purpose_4}}机构转换初访：通过现场访问，收集受审核方认证转换的原因、以往认证审核结果以及与管理体系的认证范围、产品/服务、过程、场所等有关的信息，确认能否推荐认证转换。", "{{purpose_5}}其他：{{other_purpose}}"], "logos": ["data:image/png;base64,", "data:image/png;base64,"]};
